inbound.set-body:
@{
            var input = context.Request.Body.As<JObject>(preserveContent: true);
            var e = new JObject();
            e["PartitionKey"] = "customer";
            e["RowKey"] = (string)context.Variables["newId"];
            e["name"] = input["name"];
            e["email"] = input["email"];
            if (input["city"] != null) { e["city"] = input["city"]; }
            return e.ToString();
        }

when.set-body:
@{
                    var row = context.Response.Body.As<JObject>();
                    var o = new JObject();
                    o["id"] = row["RowKey"];
                    o["name"] = row["name"];
                    o["email"] = row["email"];
                    if (row["city"] != null) { o["city"] = row["city"]; }
                    return o.ToString();
                }
